export default function App(){const [selectedId,setSelectedId]=useState('hilbert-spaces');const [query,setQuery]=useState('');const [view,setView]=useState<View>('reader');const selected=concepts.find(x=>x.id===selectedId)||concepts[0];const index=concepts.findIndex(x=>x.id===selected.id);const navigate=(id:string)=>{if(concepts.some(x=>x.id===id)){setSelectedId(id);setView('reader');window.scrollTo({top:0,behavior:'smooth'})}};const q=query.toLowerCase();const filtered=useMemo(()=>concepts.filter(x=>`${x.title} ${x.summary} ${x.group}`.toLowerCase().includes(q)),[q]);const defResults=useMemo(()=>definitions.filter(d=>`${d.title} ${d.text}`.toLowerCase().includes(q)),[q]);const title=(id:string)=>concepts.find(x=>x.id===id)?.title||'Linked concept';const links=[...selected.parents,...selected.relationships].filter((x,i,a)=>a.indexOf(x)===i);return <main className='min-h-screen bg-slate-50 text-slate-900'><header className='sticky top-0 z-20 border-b border-slate-200 bg-white/95 backdrop-blur'><div className='mx-auto flex max-w-7xl items-center gap-3 px-4 py-3 sm:px-6'><div className='flex h-9 w-9 items-center justify-center rounded-lg bg-indigo-600 text-white'><BookOpen size={19}/></div><div><p className='text-xs font-semibold uppercase tracking-[.16em] text-indigo-600'>Systematic definitions pass</p><h1 className='text-base font-bold'>Time, Quantum Cosmology, and Advaita</h1></div><div className='ml-auto hidden w-72 items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 md:flex'><Search size={16}/><input className='w-full bg-transparent text-sm outline-none' value={query} onChange={e=>setQuery(e.target.value)} placeholder={`Search ${totalNodes} graph nodes`}/></div></div></header><div className='mx-auto grid max-w-7xl lg:grid-cols-[300px_minmax(0,1fr)]'><aside className='border-r border-slate-200 bg-white p-4'><div className='mb-3 flex items-center gap-2 rounded-lg border border-slate-200 bg-slate-50 px-3 py-2 md:hidden'><Search size={16}/><input className='w-full bg-transparent text-sm outline-none' value={query} onChange={e=>setQuery(e.target.value)} placeholder='Search wiki'/></div><div className='mb-4 grid gap-2'><button onClick={()=>setView('reader')} className={cx('rounded-lg px-3 py-2 text-left text-sm font-semibold',view==='reader'?'bg-indigo-600 text-white':'bg-slate-100 text-slate-700')}>Concept reader · 37 pages</button><button onClick={()=>setView('definitions')} className={cx('rounded-lg px-3 py-2 text-left text-sm font-semibold',view==='definitions'?'bg-amber-500 text-white':'bg-amber-50 text-amber-900')}>Definitions index · 58 terms</button></div><p className='mb-2 text-xs font-bold uppercase tracking-wider text-slate-500'>Learning path · {totalNodes} graph nodes</p>{groups.map(group=><section className='mb-4' key={group}><h2 className='mb-1 text-xs font-semibold uppercase tracking-wide text-slate-500'>{group}</h2>{filtered.filter(x=>x.group===group).map(x=><button key={x.id} onClick={()=>navigate(x.id)} className={cx('flex w-full items-center gap-2 rounded-md px-2 py-1.5 text-left text-sm',x.id===selected.id&&view==='reader'?'bg-indigo-50 font-semibold text-indigo-800':'hover:bg-slate-100')}><span className='w-5 text-right text-xs text-slate-400'>{x.order}</span><span className='min-w-0 flex-1 truncate'>{x.title}</span>{x.status==='draft'&&<span className='text-[10px] font-bold text-amber-800'>DRAFT</span>}</button>)}</section>)}</aside><article className='min-w-0 p-5 sm:p-8 lg:p-10'>{view==='definitions'?<section className='max-w-4xl'><Badge tone='amber'>58 validated definition nodes</Badge><h2 className='mt-3 text-3xl font-bold'>Definitions index</h2><p className='mt-3 text-slate-600'>Each entry is also visibly embedded in the relevant reader prose.</p><div className='mt-6 grid gap-3 sm:grid-cols-2'>{defResults.map(d=><div className='rounded-xl border border-slate-200 bg-white p-4' key={d.id}><h3 className='font-bold'>{d.title}</h3><p className='mt-2 text-sm leading-6 text-slate-600'>{d.text}</p><button onClick={()=>navigate(d.target)} className='mt-3 inline-flex items-center gap-1 text-sm font-semibold text-indigo-700 hover:underline'>Learn more: {title(d.target)} <ChevronRight size={15}/></button></div>)}</div></section>:<><>{selected.group==='Optional Philosophy'&&<div className='mb-6 flex gap-3 rounded-xl border-2 border-amber-400 bg-amber-50 p-4 text-amber-950'><AlertTriangle className='shrink-0' size={20}/><div><p className='font-bold'>Draft / Under Construction / Not reviewed</p><p className='mt-1 text-sm'>This optional philosophy layer is personal exploratory material, methodologically separate from the reviewed physics and mathematics curriculum.</p></div></div>}</><div className='mb-6 flex flex-wrap gap-2'><Badge>Concept {selected.order} of 37</Badge><Badge tone={selected.status==='draft'?'draft':selected.status==='approved'?'green':'indigo'}>{selected.status.replace('_',' ')}</Badge><Badge tone='amber'>{selected.definitions.length} active definitions</Badge></div><h2 className='text-3xl font-bold tracking-tight sm:text-4xl'>{selected.title}</h2><p className='mt-4 max-w-3xl text-lg leading-8 text-slate-600'>{selected.summary}</p><section className='mt-8 max-w-4xl'><h3 className='mb-3 text-lg font-bold'>Reader notes</h3><Reader key={selected.id} page={selected} onNavigate={navigate}/></section><div className='mt-10 grid gap-5 xl:grid-cols-2'><section className='rounded-xl border border-slate-200 bg-white p-5'><h3 className='flex items-center gap-2 font-bold'><GitBranch size={17} className='text-indigo-600'/>Relationships</h3><div className='mt-3 space-y-2'>{selected.relationships.map(id=><button key={id} onClick={()=>navigate(id)} className='flex w-full items-center justify-between rounded-lg bg-slate-50 px-3 py-2 text-left text-sm hover:bg-indigo-50'>{title(id)}<ChevronRight size={15}/></button>)||<p className='text-sm text-slate-500'>Starting point.</p>}</div></section><section className='rounded-xl border border-slate-200 bg-white p-5'>